/bin/bash -lc "python3 - <<'PY'
import json,re,collections
with open('packet.json', encoding='utf-8') as f:
    p=json.load(f)
print(p['task'])
print('ITEM COUNT',len(p['items']))
for i,item in enumerate(p['items'],1):
    q=item['question']
    if q.startswith('In which '):
        kind='pack'
    elif q.startswith('Which Rel-'):
        kind='clause_release'
    elif q.startswith('Change request '):
        kind='decision_pack'
    elif q.startswith('Trace change request '):
        kind='trace'
    elif q.startswith('RAN5 recorded '):
        kind='revision'
    elif q.startswith('TSG RAN CR pack '):
        kind='pack_decisions'
    else:
        kind='UNKNOWN'
    print(json.dumps({'n':i,'id':item['id'],'kind':kind,'refs':re.findall(r'R5-\\d+|RP-\\d+|CR \\d+|TS [\\d.-]+|Rel-\\d+|clause \\S+',q),'fields':item['fields']},ensure_ascii=False))
PY"

